#include <iostream>
#include <array>
#include <string>
#include <algorithm>

int main() {
    const std::size_t arraySize = 7;
    std::array<std::string, arraySize> colors = {
        "red", "orange", "yellow", "green", "blue", "indigo", "violet"
    };

    std::cout << "Unsorted array:\n";
    for (const auto& color : colors) {
        std::cout << color << " ";
    }
    std::cout << "\n";

    // Sort elements in ascending alphabetical order
    std::sort(colors.begin(), colors.end());

    std::cout << "Sorted array:\n";
    for (const auto& color : colors) {
        std::cout << color << " ";
    }
    std::cout << "\n\n";

    // Search for existing and non-existing keys
    bool foundIndigo = std::binary_search(colors.begin(), colors.end(), "indigo");
    std::cout << "\"indigo\" " << (foundIndigo ? "was" : "was not") << " found in colors\n";

    bool foundCyan = std::binary_search(colors.begin(), colors.end(), "cyan");
    std::cout << "\"cyan\" " << (foundCyan ? "was" : "was not") << " found in colors\n";

    return 0;
}

#include <iostream>
#include <array>

const std::size_t rows = 2;
const std::size_t columns = 3;

// Pass 2D array by const reference to avoid expensive copying
void printArray(const std::array<std::array<int, columns>, rows>& a) {
    for (const auto& row : a) {
        for (const auto& element : row) {
            std::cout << element << ' ';
        }
        std::cout << '\n';
    }
}

int main() {
    // Fully initialized 2x3 array (2 rows, 3 columns)
    std::array<std::array<int, columns>, rows> array1 = {1, 2, 3, 4, 5, 6};

    // Partially initialized 2x3 array: missing final element is zero-initialized
    std::array<std::array<int, columns>, rows> array2 = {1, 2, 3, 4, 5};

    std::cout << "Values in array1 by row are:\n";
    printArray(array1);

    std::cout << "\nValues in array2 by row are:\n";
    printArray(array2);

    return 0;
}
